<script setup lang="ts">import{computed,ref,watch}from'vue';import{events,err,type Category,type EventQuery}from'./api';import{useRoute,useRouter}from'vue-router';const r=useRoute(),router=useRouter(),q=ref(String(r.query.q||'')),category=ref<Category|''>(String(r.query.category||'')as Category|''),from=ref(String(r.query.date_from||'')),to=ref(String(r.query.date_to||'')),items=ref<any[]>([]),total=ref(0),next=ref<string|null>(null),cursor=ref<string|undefined>(),loading=ref(false),error=ref<any>(),controller=ref<AbortController>();const dateError=computed(()=>from.value&&to.value&&from.value>to.value);const cats:{v:Category;l:string}[]=[{v:'model_release',l:'模型发布'},{v:'agent_tool',l:'智能体工具'},{v:'framework_sdk',l:'框架与 SDK'},{v:'research',l:'研究'},{v:'product',l:'产品'},{v:'industry',l:'产业'}];async function load(reset=true){if(dateError.value)return;controller.value?.abort();controller.value=new AbortController();loading.value=true;error.value=null;if(reset)cursor.value=undefined;const x:EventQuery={q:q.value,category:category.value||undefined,date_from:from.value||undefined,date_to:to.value||undefined,limit:10,cursor:cursor.value};router.replace({query:Object.fromEntries(Object.entries(x).filter(([,v])=>v))});try{const out=await events.list(x,controller.value.signal);items.value=reset?out.items:[...items.value,...out.items];total.value=out.total;next.value=out.next_cursor}catch(e:any){if(e.name!=='AbortError')error.value=err(e)}finally{loading.value=false}}function more(){cursor.value=next.value||undefined;load(false)}let t:number;watch([q,category,from,to],()=>{clearTimeout(t);t=window.setTimeout(()=>load(),300)},{immediate:true});</script><template><section><p class="meta">全球事件库 · 服务端稳定排序</p><h1>研究工作台</h1><p class="muted">先确认事实，再建立观点。</p><div class="two"><aside class="card"><label>关键词<input v-model="q" class="control" placeholder="标题、摘要、实体"/></label><fieldset><legend>分类</legend><label v-for="c in cats" :key="c.v" class="row"><input v-model="category" type="radio" :value="c.v"/>{{c.l}}</label><label class="row"><input v-model="category" type="radio" value=""/>全部</label></fieldset><label>从<input v-model="from" type="date" class="control"/></label><label>至<input v-model="to" type="date" class="control"/></label></aside><div><p v-if="dateError" class="status danger" role="alert">日期范围无效：起始日期不能晚于截止日期。</p><p v-else aria-live="polite" class="meta">{{loading?'正在更新匹配结果…':`精确匹配 ${total} 条事件`}}</p><div v-if="error" class="card error" role="alert">{{error.message}} <button @click="load()">重试</button></div><div v-else-if="!loading&&!items.length" class="card empty">这个范围内没有事件。可调整条件或清除筛选。</div><article v-for="x in items" :key="x.id" class="card event"><span class="pill">{{cats.find(c=>c.v===x.category)?.l}}</span><span class="meta"> {{x.event_date||'日期未知'}}</span><h2><RouterLink :to="`/events/${x.id}${$route.fullPath.includes('demo=1')?'?demo=1':''}`">{{x.title_zh}}</RouterLink></h2><p class="muted">{{x.summary_zh}}</p><p class="meta">重要度 {{x.importance}}/5 · {{x.source_count}} 个来源 · {{x.evidence_count}} 条关联证据</p></article><button v-if="next&&!loading" @click="more">加载更多</button></div></div></section></template>


